# Dado un polinomio y un rango, encuentra TODAS las raíces
# buscando cambios de signo y aplicando bisección en cada intervalo.

def evaluar(coefs, x):
    """coefs = [a0, a1, a2, ...] para a0 + a1*x + a2*x^2 + ..."""
    return sum(c * x**i for i, c in enumerate(coefs))

def biseccion(f, a, b, tol=1e-10, max_iter=100):
    if f(a) * f(b) >= 0:
        return None
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol or (b - a) / 2 < tol:
            return c
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return c

def encontrar_raices(coefs, inicio, fin, paso=0.1):
    f = lambda x: evaluar(coefs, x)
    raices = []
    a = inicio
    while a < fin:
        b = a + paso
        if f(a) * f(b) < 0:
            raiz = biseccion(f, a, b)
            if raiz is not None:
                # Verificar que no está duplicada
                if not any(abs(raiz - r) < 1e-6 for r in raices):
                    raices.append(raiz)
        a = b
    return raices

# x³ - x - 2 = 0 → coefs = [-2, -1, 0, 1]
coefs = [-2, -1, 0, 1]
raices = encontrar_raices(coefs, -5, 5)
for r in raices:
    print(f"Raíz: {r:.10f}")

# Mal: una función que hace demasiado
def procesar(datos):
    # limpia
    datos = [x for x in datos if x is not None]
    # ordena
    datos = sorted(datos)
    # calcula estadísticas
    media = sum(datos) / len(datos)
    # imprime
    print(f"Media: {media}")
    # guarda
    with open("out.txt", "w") as f:
        f.write(str(datos))

# Bien: funciones separadas
def limpiar(datos):
    return [x for x in datos if x is not None]

def ordenar(datos):
    return sorted(datos)

def media(datos):
    return sum(datos) / len(datos)

def guardar(datos, ruta):
    with open(ruta, "w") as f:
        f.write(str(datos))
